-- Complements to tables generated by Hibernate. All names stay in the original schema.
-- Custom statement separator (^^^) keeps the PostgreSQL DO block intact.
SET search_path TO barrocontrol, pg_catalog;
^^^
CREATE UNIQUE INDEX IF NOT EXISTS uq_usuario_correo
    ON barrocontrol.usuario (lower(btrim(correo)));
^^^
-- JPA maps both associations individually; this FK enforces their shared cash register.
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'fk_venta_corte_misma_caja'
          AND conrelid = 'barrocontrol.venta'::regclass
    ) THEN
        ALTER TABLE barrocontrol.venta
            ADD CONSTRAINT fk_venta_corte_misma_caja
            FOREIGN KEY (id_corte_caja, id_caja)
            REFERENCES barrocontrol.corte_caja (id, id_caja);
    END IF;
END
$$;
^^^
CREATE OR REPLACE VIEW vw_venta AS
SELECT v.*, COALESCE(d.total, 0::NUMERIC) AS total
FROM venta v
LEFT JOIN (
    SELECT id_venta, SUM(subtotal) AS total
    FROM detalle_venta
    GROUP BY id_venta
) d ON d.id_venta = v.id;
^^^

CREATE OR REPLACE VIEW vw_corte_caja AS
SELECT c.*, COALESCE(v.total_ventas, 0::NUMERIC) AS total_ventas
FROM corte_caja c
LEFT JOIN (
    SELECT id_corte_caja, SUM(total) AS total_ventas
    FROM vw_venta
    GROUP BY id_corte_caja
) v ON v.id_corte_caja = c.id;
^^^

-- Vista auxiliar: total del pedido, pagos registrados y saldo.
-- Los pagos NO se suman a total_ventas: son un flujo distinto en el diagrama.
CREATE OR REPLACE VIEW vw_pedido AS
SELECT p.*,
       COALESCE(d.total, 0::NUMERIC) AS total,
       COALESCE(a.total_pagado, 0::NUMERIC) AS total_pagado,
       COALESCE(d.total, 0::NUMERIC) - COALESCE(a.total_pagado, 0::NUMERIC) AS saldo
FROM pedido p
LEFT JOIN (
    SELECT id_pedido, SUM(subtotal) AS total
    FROM detalle_pedido
    GROUP BY id_pedido
) d ON d.id_pedido = p.id
LEFT JOIN (
    SELECT id_pedido, SUM(monto) AS total_pagado
    FROM pago_pedido
    GROUP BY id_pedido
) a ON a.id_pedido = p.id;
^^^

-- Roles base requeridos por el registro de propietarios y empleados (idempotente).
INSERT INTO barrocontrol.rol (nombre)
VALUES ('PROPIETARIO'), ('EMPLEADO')
ON CONFLICT (nombre) DO NOTHING;
^^^
